using System;

namespace MUD.CoreApi
{
    /// <summary>
    /// Identifies one front-end session. The value is an opaque random string generated by core when the session is
    /// opened (decision D46): it is unguessable and never reused. A front end must treat it as opaque and only pass
    /// it back to core; it must not parse it or build one itself.
    /// </summary>
    public readonly struct SessionId : IEquatable<SessionId>
    {
        private readonly string _value;

        /// <summary>Wraps a value that core generated. Only core creates new ids.</summary>
        public SessionId(string value)
        {
            _value = value;
        }

        /// <summary>The opaque text of the id; empty for a default (unset) id.</summary>
        public string Value { get { return _value ?? string.Empty; } }

        /// <summary>True for a default (unset) id, which never identifies a session.</summary>
        public bool IsEmpty { get { return string.IsNullOrEmpty(_value); } }

        public bool Equals(SessionId other)
        {
            return string.Equals(Value, other.Value, StringComparison.Ordinal);
        }

        public override bool Equals(object obj)
        {
            return obj is SessionId other && Equals(other);
        }

        public override int GetHashCode()
        {
            return StringComparer.Ordinal.GetHashCode(Value);
        }

        public override string ToString()
        {
            return Value;
        }

        public static bool operator ==(SessionId left, SessionId right)
        {
            return left.Equals(right);
        }

        public static bool operator !=(SessionId left, SessionId right)
        {
            return !left.Equals(right);
        }
    }
}
